#include "agent/tool_runtime/execution_control.hpp"
#include <cassert>
#include <filesystem>
#include <iostream>
#include <unistd.h>
using namespace agent_framework::tool_runtime;
int main(){auto path=(std::filesystem::temp_directory_path()/ ("ltw8-control-"+std::to_string(::getpid())+".sqlite")).string();std::filesystem::remove(path);SQLiteExecutionControlStore store(path);ExecutionControlEnvelope e;e.invocation_id="inv-1";e.tenant_id="tenant-a";e.deadline_at_ms=5000;e.backpressure={10,2,BackpressureMode::DropEphemeral};assert(store.create(e));auto r=store.reserve("inv-1",8,1,false);assert(r.accepted);auto drop=store.reserve("inv-1",4,1,true);assert(drop.dropped);assert(store.release("inv-1",8,1));auto requested=store.request_cancel("inv-1","user",100);assert(requested&&requested.generation==1);auto claim=store.claim("inv-1","worker-a",100,20);assert(claim&&claim->stage==CancellationStage::Requested);assert(store.advance("inv-1","worker-a",claim->fencing_token,claim->revision,CancellationStage::Cooperative,110,false,""));assert(!store.advance("inv-1","stale",claim->fencing_token,claim->revision+1,CancellationStage::Kill,120,false,""));{SQLiteExecutionControlStore restarted(path);auto due=restarted.recoverable(110,10);assert(due.size()==1&&due[0].stage==CancellationStage::Cooperative);auto takeover=restarted.claim("inv-1","worker-b",121,20);assert(takeover&&takeover->fencing_token>claim->fencing_token);assert(restarted.advance("inv-1","worker-b",takeover->fencing_token,takeover->revision,CancellationStage::Reconciling,130,false,""));}std::filesystem::remove(path);std::cout<<"phase4 execution control tests passed\n";}
